<template>
  <DefaultLayout>
    <v-container fluid>
      <v-row justify="center">
        <v-col cols="12" md="8" lg="7">
          <v-sheet class="payment-container" elevation="0">
            <div class="message-wrapper">
              <h4 class="font-bold text-h6 py-3">{{ CONTENT.paymentSuccess.title }}</h4>
              <p class="font-thin">{{ CONTENT.paymentSuccess.message }}</p>
              <v-btn
                  :text="CONTENT.buttonText.goBackHome"
                  variant="flat"
                  :color="colors.primary"
                  size="large"
                  class="my-5"
                  @click="goToHomepage">
              </v-btn>
            </div>
            <v-skeleton-loader height="350" class="play" v-if="!isVisible"></v-skeleton-loader>
              <video
                  ref="videoEl"
                  :class="isVisible  ?  'play' : 'invisible' "
                  autoplay
                  loop
                  muted="muted"
                  playsinline
                  controlslist="nodownload"
                  :poster="poster"
                  :preload="preload"
                  @play="handlePlay"
              >
                <source v-if="isVisible" :src="src" :type="type">
              </video>
          </v-sheet>
        </v-col>
      </v-row>
    </v-container>
  </DefaultLayout>
</template>

<script>

import DefaultLayout from "@/layouts/DefaultLayout.vue";
import CheckoutMixins from "@/utils/checkout-mixins";

import STATIC_CONTENT from "@/static/content.json";
import colors from "@/utils/colors";

export default {
  mixins: [CheckoutMixins],
  name: "PaymentRedirect",
  props: {
    src: {type: String, default: 'https://flitt.com/wp-content/uploads/2024/11/explainer-16by9.mp4'},
    poster: {type: String, default: 'https://flitt.com/wp-content/uploads/2024/09/white-placeholder.png'},
    type: {type: String, default: 'video/mp4'},
    preload: {type: String, default: 'none'},
  },
  components: {
    DefaultLayout,
  },
  computed: {
    CONTENT() {
      return STATIC_CONTENT;
    },
  },
  data() {
    return {
      colors: colors,
      isVisible: false,
      observer: null,
    };
  },
  mounted() {
    this.clearCart()
    this.observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          this.isVisible = true
          this.observer.disconnect()
        }
      })
    }, {
      threshold: 0.01
    })

    this.observer.observe(this.$refs.videoEl)
  },
  beforeDestroy() {
    if (this.observer) this.observer.disconnect()
  },
  methods: {
    handlePlay() {
      if (!this.isVisible) this.isVisible = true
    },
    goToHomepage() {
      this.$router.push('/');
    },
  },
}
</script>

